{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "table_6",
      "quote": "Identify the report as a systematic review | 1-3",
      "reason": "The document title explicitly states 'a systematic review on the use of touch in healthcare professions', and the PRISMA checklist confirms item 1 is reported."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Touch, communication and affect: a systematic review on the use of touch in healthcare professions",
      "reason": "The title conveys the key topic (touch, communication, affect) and the population/context (healthcare professions), reflecting the review's main objective."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The title contains no supplementary information such as analysis method, study designs, or update/living-review status; no evidence of such details was found."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "In light of this brief background analysis, the present review sets itself apart from previous ones by attempting to understand the communicative, social and affective dimensions of touch in healthcare and nursing professions... teases out conceptual and methodological issues that might have been partly obscured in the studies examined and overlooked in previous reviews.",
      "reason": "The Aim section describes the current state of knowledge (previous reviews providing descriptive accounts, obscured conceptual/methodological issues) and the uncertainties the review addresses; the Abstract background also frames existing understanding of touch as instrumental vs expressive."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "the present review sets itself apart from previous ones by attempting to understand the communicative, social and affective dimensions of touch in healthcare and nursing professions, in both its instrumental and expressive instances.",
      "reason": "The importance and need for the review are explained: prior reviews gave descriptive accounts and overlooked socio-affective dimensions, motivating a new critical synthesis (supported also by text_9: 'most of the reviews on the topic generated thus far have focused on providing descriptive accounts')."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "First, most of the reviews on the topic generated thus far have focused on providing descriptive accounts to guide practitioners and policymakers.",
      "reason": "The need for the current review relative to existing reviews is explained (previous reviews were descriptive; this one is critical/theoretical), but the retrieved evidence does not show specific identification and citation of the previous review(s) as an update or replication."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a qualitative thematic synthesis of social/communicative dimensions of touch, not a review of intervention effects, so describing a mechanism of action of an intervention does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is an exploratory qualitative thematic synthesis, not an evaluation of a complex intervention with components and outcomes, so a logic model is not required."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "A PICo (Population, Interest, Context) framework ([45]; see also: [46]) was used to formulate the preliminary question 'What are care-givers' (i.e. allied health professionals, nurses, doctors, carers) [Population] actual uses and experiences of touch [Interest] when providing real and direct medical care to patients [Context]?'",
      "reason": "The review's objective is explicitly stated as a research question formulated using the PICo framework, and the abstract (text_2) also states the review's aims."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "From this question, PICo was also used to devise inclusion and exclusion criteria and to inform an initial set of search terms.",
      "reason": "The review is exploratory/qualitative rather than a review of intervention effects; the planned focus is stated via PICo (Population, Interest, Context), an appropriate variant of PICO for this review type."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Both qualitative and quantitative studies were considered eligible, but non-empirical studies were not ('non-empirical' exclusion criterion). No specific sociometric variables (e.g. sex, age, socioeconomic status of participants) were sought, and studies were not excluded on the basis of their design (e.g. number of participants, methods).",
      "reason": "Study characteristics for eligibility are specified via the PICo framework (Population, Interest, Context), eligible designs (qualitative and quantitative empirical studies), and settings (allied health professions, nursing, medicine, care work), with detailed exclusion criteria in Table 1."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "studies from all years and in any language spoken by the team (i.e. English, Italian, French, Spanish, Finnish) were included ('Language' exclusion criterion). Both qualitative and quantitative studies were considered eligible, but non-empirical studies were not",
      "reason": "Report characteristics are specified: all publication years included, language restrictions (English, Italian, French, Spanish, Finnish), and publication status (empirical studies only, excluding non-empirical pieces)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a thematic synthesis of touch practices, not an outcome-based review; no outcome measurement vs outcome reporting distinction is relevant to the eligibility criteria reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "themes were constructed inductively, with new codes and themes created as necessary. Furthermore, the review followed the principles of thematic synthesis [63], identifying patterns and themes",
      "reason": "The synthesis approach (inductive thematic synthesis with descriptive and analytical themes) is described, but the evidence does not explicitly specify predefined groups used in each synthesis linked to comparisons in the review objectives; grouping emerged inductively rather than being specified a priori."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Two of them ('language' and 'non-empirical') were based on the team expertise and the general aim of this review (i.e. capturing empirical social analysis over anecdotal case studies or philosophical discussions)",
      "reason": "Rationales for notable restrictions (language and non-empirical criteria) are explicitly provided, and Table 1 gives reasons for each exclusion criterion (e.g. neo-natal interventions excluded due to different properties of touch with pre-verbal children)."
    }
  ],
  "confidence": 88
}

